    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    coords = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            counts[value] = counts.get(value, 0) + 1
            coords.setdefault(value, []).append((r, c))
    bg = max(counts, key=counts.get)
    ones = coords.get(1, [])
    sixes = coords.get(6, [])

    # 1-markers connected by a diagonal are joined with color 1.
    # Record their diagonal lines; 6-markers on such a line generate a
    # full perpendicular diagonal of color 6.
    selected_sixes = set()
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue
            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            for k in range(abs(dr) + 1):
                r, c = r1 + k * sr, c1 + k * sc
                if grid[r][c] == bg or grid[r][c] == 1:
                    out[r][c] = 1
            # Include 6 markers anywhere on the same infinite diagonal.
            for r, c in sixes:
                if (c - c1) * dr == (r - r1) * dc:
                    selected_sixes.add((r, c))

    # Each selected 6 projects along the perpendicular diagonal, retaining
    # all original clue pixels at crossings.
    for r0, c0 in selected_sixes:
        for r in range(h):
            c = c0 - (r - r0)  # opposite diagonal slope
            if 0 <= c < w and grid[r][c] == bg:
                out[r][c] = 6
    return out
