    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    coords = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            counts[value] = counts.get(value, 0) + 1
            coords.setdefault(value, []).append((r, c))
    bg = max(counts, key=counts.get)
    ones, sixes = coords.get(1, []), coords.get(6, [])

    # Join same-color marker pairs on diagonals, preserving crossings.
    for color, points in ((1, ones), (6, sixes)):
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                dr, dc = r2-r1, c2-c1
                if dr == 0 or abs(dr) != abs(dc):
                    continue
                sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                for k in range(abs(dr)+1):
                    r, c = r1+k*sr, c1+k*sc
                    if grid[r][c] in (bg, color):
                        out[r][c] = color

    # A 6 lying strictly between two 1 markers on their connecting diagonal
    # projects a perpendicular 6 diagonal across the grid.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i+1:]:
            dr, dc = r2-r1, c2-c1
            if dr == 0 or abs(dr) != abs(dc):
                continue
            sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
            for r0, c0 in sixes:
                if (c0-c1)*dr != (r0-r1)*dc:
